    "scale": "S(小型)",
    "profile": "晋江市溢泰织造机械有限公司是以生产先进装配制造业 ：航天、环保、医疗等材料织造机械以及高档服装辅料纺织机械等机械产品、经营进出口国际贸易的多元化公司。公司成立于2003年，地处福建晋江市着名侨乡--龙湖镇晋南工业区，地理位置优越，交通便利，拥有职工100多名，其中高级管理人员及专业技术人才80多名，拥有2家公司--厦门溢泰实业有限公司、晋江市溢泰织造机械有限公司。溢泰公司在新品研发及产品创新上不断突破，加大研发投入，确保产品达到国内以及世界先进水平。经过十几年的发展，不仅成为国内先进装配制造业航天、环保、医疗纺织机械较大的机械供应商之一，各大城市均有我司的办事处及分公司，企业在国际上享有较高的声誉。YITAI品牌一直深受用户的欢迎。在一些较发达的国家如:欧美、中东、南非等地区均有我司的办事处或供应商。公司近年主推产品：数控一代提花织带机、数控一代高速钩编机、高速编织机等产品，主要应用在航天、环保、医疗等相关织造材料的生产。YITAI品牌的市场占有率不断攀升，目前的产能及原有生产规模已不能满足市场及客户的需求。公司以纺织机械科技为依托，延伸至数控科技领域，开展多元化经营。",
    "businessScope": "一般项目：纺织专用设备制造；纺织专用设备销售；专用设备制造（不含许可类专业设备制造）；机械设备销售；机械设备研发；普通机械设备安装服务；租赁服务（不含许可类租赁服务）；五金产品制造；五金产品批发；五金产品零售；纺织专用测试仪器制造；机械零件、零部件加工；机械零件、零部件销售。（除依法须经批准的项目外，凭营业执照依法自主开展经营活动）"
