    "profile": "福建省澳龙环保新材料有限公司（原：福建省澳龙树脂化工有限公司）筹建于2007年，位于泉州市惠安县辋川镇石化工业小区，属市引进的外商投资企业，由晋江市澳龙涂料有限公司投资创立，注册资金2000万港币，厂区面积18000平方米，主要从事研发、生产及销售油性、水性油漆涂料及水性环保染料色浆、免水洗染料色浆、纳米色浆、纺织印染技术及纺织新材料等。公司产品符合欧盟ROSH以及REACH法规标准，严格的质量管理体系与制造和核心技术开发能力，位局省产品行业创新地位，公司具有年产5000吨的油漆、金属烤漆、塑胶漆、水性电镀金油、水性呖架油、水性拉链漆、水性拉链呖架油、水性烤漆及免水洗印染色浆、无水印花色浆等十几大类中高端型涂料和纳米色浆，年产值上亿。同时在涂料、印染行业的应用，涉及十几个大类，及其配套产品达上百个品种，销售领域及其售后市场业务遍及中国各地，得到了新老客户的良好评价。公司自创立以来，秉承诚信立业、品质稳定、积极创新、服务及时的经营理念，以客户需求为中心，加强技术改进，严把产品检验，精诚为广大客户提供优质的产品和服务。",
