    "profile": "特步（中国）有限公司，于2008年6月3日正式在港交所挂牌上市，以“时尚运动”的独特定位为消费者带来了“非一般的感觉。”特步一直以中国跑步运动领导者为使命。自2007年起，特步在跑步领域频频发力，先后携手北京、上海、中国香港、台北、厦门、广州、武汉等二十多个城市的马拉松，成为大中华区赞助马拉松赛事较多的运动品牌。除囊括众多跑步赛事资源，奥运竞走巅峰级运动员陈定、王镇、蔡泽林、短跑名将谢震业等体坛之星也悉数纳入跑步代言阵营。“爱跑步，爱特步”的口号深入人心。同时，作为中国青少年足球运动发展与普及的推动者，特步通过赞助全国性的校园联赛，如全国大学生足球联赛、全国大学生五人制足球联赛、全国高中校园足球联赛等赛事，来布局校园足球，与青少年互动，助力中国足球蓬勃发展。2010年，特步签约英超伯明翰俱乐部，2011年签约西甲劲旅比利亚雷亚尔。2016年，特步更是牵手国际知名球星、乌克兰“核弹头”安德烈·舍甫琴科，共同打造专业足球产品并成功推向市场。2016年4月，特步还推出了足球战略“锋芒计划”，即以规划构筑中国足球根基为使命，通过赛事计划、培训计划、产品计划和推广计划等四大举措，希望在5年时间里服务500万青少年。此外，特步连续三届赞助全国运动会，并于2017年再度成为十三运东道主天津、福建、解放军、吉林及中国香港等代表团的合作伙伴。2015年，特步还成为中华人民共和国青年运动会体育用品合作伙伴。2015年，特步强势回归运动，提出以消费者体验为核心的“3+”战略。 “产品+”，让产品升级换代；“体育+”，将产品及服务融为一体；“互联网+”，因应生活方式趋势，线上线下充分互动。注重专业性的同时，特步秉持“体娱营销”双轨制，先后签约谢霆锋、TWINS、潘玮柏、蔡依林、桂纶镁、韩庚、天天兄弟、李易峰、林珍娜、UNIQ、杜天皓、汪东城、赵丽颖、林更新、乐华七子NEXT等多位当红艺人，传承并巩固品牌时尚调性。",
